package com.zhou.craft.controller;
import com.zhou.craft.dto.WorkStatusForm;import com.zhou.craft.model.*;import com.zhou.craft.repo.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;import java.util.stream.Collectors;
@RestController @RequestMapping("/api/admin")
public class AdminController{private final UserRepository users;private final CraftWorkRepository works;private final WorkReviewRepository reviews;private final CraftOrderRepository orders;
public AdminController(UserRepository users,CraftWorkRepository works,WorkReviewRepository reviews,CraftOrderRepository orders){this.users=users;this.works=works;this.reviews=reviews;this.orders=orders;}
@GetMapping("/users")public List<UserAccount> users(){return users.findAll();}
@PutMapping("/users/{id}/enabled")public UserAccount enabled(@PathVariable Long id,@RequestParam boolean enabled){UserAccount u=users.findById(id).orElseThrow();if(!"USER".equals(u.getRole()))throw new IllegalStateException("固定管理员和商户账号不能在此停用");u.setEnabled(enabled);return users.save(u);}
@GetMapping("/works")public List<CraftWork> works(){return works.findAll().stream().sorted(Comparator.comparing(CraftWork::getId).reversed()).toList();}
@PutMapping("/works/{id}/status")public CraftWork workStatus(@PathVariable Long id,@RequestBody WorkStatusForm f){if(!Set.of(CraftWork.APPROVED,CraftWork.REJECTED,CraftWork.PENDING).contains(f.status()))throw new IllegalStateException("非法审核状态");CraftWork w=works.findById(id).orElseThrow();w.setStatus(f.status());return works.save(w);}
@PutMapping("/works/{id}/featured")public CraftWork featured(@PathVariable Long id,@RequestParam boolean featured){CraftWork w=works.findById(id).orElseThrow();w.setFeatured(featured);return works.save(w);}
@GetMapping("/reviews")public List<WorkReview> reviews(){return reviews.findAllByOrderByCreatedAtDesc();}
@DeleteMapping("/reviews/{id}")public Map<String,Object> deleteReview(@PathVariable Long id){reviews.deleteById(id);return Map.of("success",true);}
@GetMapping("/stats")public Map<String,Object> stats(){List<CraftWork>ws=works.findAll();List<CraftOrder>os=orders.findAll();List<UserAccount>us=users.findAll();Map<String,Long>categories=ws.stream().filter(w->CraftWork.APPROVED.equals(w.getStatus())).collect(Collectors.groupingBy(CraftWork::getCategory,LinkedHashMap::new,Collectors.counting()));Map<String,Long>orderStatus=os.stream().collect(Collectors.groupingBy(CraftOrder::getStatus,LinkedHashMap::new,Collectors.counting()));Map<String,Long>roles=us.stream().collect(Collectors.groupingBy(UserAccount::getRole,LinkedHashMap::new,Collectors.counting()));LinkedHashMap<String,Long>seven=new LinkedHashMap<>();LocalDate today=LocalDate.now();for(int i=6;i>=0;i--){LocalDate d=today.minusDays(i);long count=os.stream().filter(o->o.getCreatedAt()!=null&&o.getCreatedAt().toLocalDate().equals(d)).count();seven.put(d.getMonthValue()+"/"+d.getDayOfMonth(),count);}return Map.of("categories",categories,"orderStatus",orderStatus,"roles",roles,"sevenDayOrders",seven);}}